"use strict";(function(){"use strict";window.SnakkActions.on("add-poll-option",()=>{const t=document.getElementById("poll-options-list");if(!t||t.children.length>=20)return;const e=document.createElement("input");e.type="text",e.name="PollOptions",e.className="input w-full input-sm",e.placeholder="Option "+(t.children.length+1),t.appendChild(e)});const n=document.getElementById("poll-segmented-check"),c=document.getElementById("segment-fields");n&&c&&n.addEventListener("change",()=>{c.classList.toggle("hidden",!n.checked)});const l=document.getElementById("poll-close-date-check"),d=document.getElementById("close-date-field");l&&d&&l.addEventListener("change",()=>{d.classList.toggle("hidden",!l.checked)})})();
